`timescale 1ns/1ns
module testbench();

// === Global Sync Signal ===
reg llm_go_signal = 1;

    reg rst,valid_in;
	reg clk=1;
	reg[7:0] data_in;
	wire valid_out;
	wire [15:0] data_out;

width_8to16 dut(
	.clk (clk),   
	.rst_n(rst),
	.valid_in(valid_in),
	.data_in(data_in),
	.valid_out(valid_out),
	.data_out(data_out)
);
	always #5 clk = ~clk;  

integer error = 0;
initial begin
	rst=0;valid_in=0;
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

 	#10 rst=1;valid_in=1;data_in=8'b10100000;
	// $display("data_out = %b", data_out);
	// $display("valid_out = %b", valid_out);
	error = valid_out ==0 ? error : error+1; 
	#10 data_in=8'b10100001; 
	// $display("data_out = %b", data_out); 
	#10 data_in=8'b10110000;
	// $display("data_out = %b", data_out); 
	// $display("valid_out = %b", valid_out);
	error = (data_out == 16'b1010000010100001 && valid_out ==1 )? error : error+1;
	#10 valid_in=0;
	#20 valid_in=1;data_in=8'b10110001; 
	#10 valid_in=0;
	// $display("data_out = %b", data_out); 
	// $display("valid_out = %b", valid_out);
	error = (data_out == 16'b1011000010110001 && valid_out ==1 )? error : error+1;
	#30

	if (error == 0) begin
		$display("===========Your Design Passed===========");
	end
	else begin
	$display("===========Test completed with %d / 3 failures===========", error);
	end

	$finish;
end  





        ///////////////////added
        integer file_mantra;
        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "valid_out,");
      $fwrite(file_mantra, "data_out,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", valid_out);
        $fwrite(file_mantra, "%h, ", data_out);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    $display("LLM: Starting deterministic test patterns...");

    // Initialize Inputs
    rst = 0;
    valid_in = 0;
    data_in = 8'h00;

    // Apply Reset
    #20;
    rst = 1;
    #20;

    // -------------------------------------------------------
    // Test 1: Basic Functionality (0xAA, 0x55 -> 0xAA55)
    // -------------------------------------------------------
    // Targets: Basic data path, stitching logic
    @(posedge clk);
    #1;
    valid_in = 1;
    data_in = 8'hAA; // First byte (Upper)
    @(posedge clk);
    #1;
    data_in = 8'h55; // Second byte (Lower)
    @(posedge clk);
    #1;
    valid_in = 0;
    data_in = 8'h00;
    #20; 

    // -------------------------------------------------------
    // Test 2: Back-to-Back Transactions (Burst Mode)
    // -------------------------------------------------------
    // Targets: Flag logic, blocking/non-blocking assignments
    // Pair 1: 0xFF, 0x00 -> 0xFF00
    // Pair 2: 0x0F, 0xF0 -> 0x0FF0
    @(posedge clk);
    #1;
    valid_in = 1;
    data_in = 8'hFF; // Byte 1 of Pair 1
    @(posedge clk);
    #1;
    data_in = 8'h00; // Byte 2 of Pair 1
    @(posedge clk);
    #1;
    data_in = 8'h0F; // Byte 1 of Pair 2 (Immediately after)
    @(posedge clk);
    #1;
    data_in = 8'hF0; // Byte 2 of Pair 2
    @(posedge clk);
    #1;
    valid_in = 0;
    data_in = 0;
    #20;

    // -------------------------------------------------------
    // Test 3: Interrupted Valid (Gaps)
    // -------------------------------------------------------
    // Targets: Flag retention, state stability
    // Byte 1, Wait, Byte 2
    @(posedge clk);
    #1;
    valid_in = 1;
    data_in = 8'h12; // Byte 1
    @(posedge clk);
    #1;
    valid_in = 0;    // Gap - flag should remain high
    data_in = 8'h00;
    @(posedge clk);
    @(posedge clk);
    #1;
    valid_in = 1;
    data_in = 8'h34; // Byte 2
    @(posedge clk);
    #1;
    valid_in = 0;
    #20;

    // -------------------------------------------------------
    // Test 4: Reset in the middle (Partial sequence abort)
    // -------------------------------------------------------
    // Targets: Reset logic, flag reset
    @(posedge clk);
    #1;
    valid_in = 1;
    data_in = 8'hA5; // Byte 1
    @(posedge clk);
    #1;
    // Instead of Byte 2, we reset
    rst = 0; 
    valid_in = 0;
    #20;
    rst = 1;
    #20;
    // Now send a full valid sequence to ensure state machine recovered
    @(posedge clk);
    #1;
    valid_in = 1;
    data_in = 8'hCC; // Byte 1
    @(posedge clk);
    #1;
    data_in = 8'hDD; // Byte 2
    @(posedge clk);
    #1;
    valid_in = 0;
    #20;

    // -------------------------------------------------------
    // Test 5: Walking 1s (Bit-level check)
    // -------------------------------------------------------
    // Targets: Bit-select boundaries, wiring errors
    // Pair: 00000001, 10000000 -> 0180
    @(posedge clk);
    #1;
    valid_in = 1;
    data_in = 8'h01; // LSB of upper byte
    @(posedge clk);
    #1;
    data_in = 8'h80; // MSB of lower byte
    @(posedge clk);
    #1;
    valid_in = 0;
    #20;

    // Pair: 10000000, 00000001 -> 8001
    @(posedge clk);
    #1;
    valid_in = 1;
    data_in = 8'h80; // MSB of upper byte
    @(posedge clk);
    #1;
    data_in = 8'h01; // LSB of lower byte
    @(posedge clk);
    #1;
    valid_in = 0;
    #20;

    // 4. Cleanup / Handover
    $display("LLM: Tests Finished. Handing over to Original TB...");
    rst = 0; // Reset state for original TB
    valid_in = 0;
    data_in = 0;
    llm_go_signal = 0;
    // DO NOT call $finish here.
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

